class BrowserHistory {
    private final Deque<String> backStack = new ArrayDeque<>();      // pages behind the current one
    private final Deque<String> forwardStack = new ArrayDeque<>();   // pages ahead of it
    private String curr;

    public BrowserHistory(String homepage) { curr = homepage; }

    public void visit(String url) {
        backStack.push(curr);
        curr = url;
        forwardStack.clear();                    // a new visit clears forward history
    }

    public String back(int steps) {
        while (steps > 0 && !backStack.isEmpty()) {
            forwardStack.push(curr);
            curr = backStack.pop();
            steps--;
        }
        return curr;
    }

    public String forward(int steps) {
        while (steps > 0 && !forwardStack.isEmpty()) {
            backStack.push(curr);
            curr = forwardStack.pop();
            steps--;
        }
        return curr;
    }
}

