class BrowserHistory {
  constructor(homepage) {
    this.pages = [homepage];
    this.curr = 0;                     // index of the page on screen
    this.last = 0;                     // the furthest page forward can reach
  }
  visit(url) {
    this.curr++;
    if (this.curr === this.pages.length) this.pages.push(url);
    else this.pages[this.curr] = url;  // overwrite old forward history
    this.last = this.curr;             // nothing beyond it counts any more
  }
  back(steps) {
    this.curr = Math.max(0, this.curr - steps);
    return this.pages[this.curr];
  }
  forward(steps) {
    this.curr = Math.min(this.last, this.curr + steps);
    return this.pages[this.curr];
  }
}

