        return self.pages[self.curr]

class BrowserHistory {
    private final List<String> pages = new ArrayList<>();
    private int curr = 0;                    // index of the page on screen
    private int last = 0;                    // the furthest page forward can reach

    public BrowserHistory(String homepage) { pages.add(homepage); }

    public void visit(String url) {
        curr++;
        if (curr == pages.size()) pages.add(url);
        else pages.set(curr, url);           // overwrite old forward history
        last = curr;                         // nothing beyond it counts any more
    }

    public String back(int steps) {
        curr = Math.max(0, curr - steps);
        return pages.get(curr);
    }

    public String forward(int steps) {
        curr = Math.min(last, curr + steps);
        return pages.get(curr);
    }
}

